sys_ux_client_script.required_translations:
[
    {
        "message": "value builder task created successfully"
    },
    {
        "message": "Failed to update Property"
    },
    {
        "message": "An error occurred while updating the property"
    }
]

sys_ux_client_script.script:
async function handler({ api, event, helpers, imports }) {
    if (!helpers.snHttp || typeof helpers.snHttp !== "function") {
        console.error("Error: helpers.snHttp is not properly initialized or callable.");
        return;
    }

    try {
        const response = await helpers.snHttp("/api/985627/value_builder_task10", {
            method: "POST",
            headers: {
                "Content-Type": "application/json",
            },
            body: JSON.stringify({}),
        });

        console.log("Full Response:", response);

        if (response.status === 200 || response.response.result.status == "success") {
            const createdTasks = response.response.result.created_tasks?.join(", ") || "No tasks created";
            const processedProps = response.response.result.processed_properties?.join(", ") || "No properties processed";

            api.emit("NOW_UXF_PAGE#ADD_NOTIFICATIONS", {
                items: [
                    {
                        id: "alert2",
                        status: "positive",
                        icon: "info-circle-outline",
                        content: await helpers.translate("value builder task created successfully"),
                        action: { type: "dismiss" },
                    },
                ],
            });
        } else {
            console.error("Failed to update Property:", response);

            api.emit("NOW_UXF_PAGE#ADD_NOTIFICATIONS", {
                items: [
                    {
                        id: "alert2",
                        status: "critical",
                        icon: "info-circle-outline",
                        content: await helpers.translate("Failed to update Property"),
                        action: { type: "dismiss" },
                    },
                ],
            });
        }
    } catch (error) {
        console.error("API Call Failed:", error.message || error);

        if (error.response) {
            console.error("Error Response:", error.response);
        } else if (error.data) {
            console.error("Error Data:", error.data);
        }

        api.emit("NOW_UXF_PAGE#ADD_NOTIFICATIONS", {
            items: [
                {
                    id: "alert2",
                    status: "critical",
                    icon: "info-circle-outline",
                    content: await helpers.translate("An error occurred while updating the property"),
                    action: { type: "dismiss" },
                },
            ],
        });
    }
}
